package pe.edu.upeu.autoandes.entity;
import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*;
@Entity @Table(name="orden_servicio") @Getter @Setter @NoArgsConstructor
public class OrdenServicio { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false, unique=true, length=9) private String numero; @Column(nullable=false) private LocalDateTime fecha; @ManyToOne(fetch=FetchType.LAZY, optional=false) @JoinColumn(name="vehiculo_id", nullable=false) private Vehiculo vehiculo; @Column(nullable=false) private Long kilometraje; @Enumerated(EnumType.STRING) @Column(nullable=false, length=12) private EstadoOrden estado=EstadoOrden.REGISTRADA; @Column(nullable=false, precision=10, scale=2) private BigDecimal total=BigDecimal.ZERO; @Column(name="usuario_registro", nullable=false, length=30) private String usuarioRegistro; @Column(name="motivo_anulacion", length=200) private String motivoAnulacion; @OneToMany(mappedBy="orden", cascade=CascadeType.ALL, orphanRemoval=true) private List<DetalleOrden> detalles=new ArrayList<>(); public void agregarDetalle(DetalleOrden d){detalles.add(d); d.setOrden(this);} }
